cd /tmp && O=/tmp/orig/executable
# physical core count
python3 -c "
import re
s=open('/proc/cpuinfo').read()
pairs=set()
p=c=None
for line in s.splitlines():
    if line.startswith('physical id'): p=line.split(':')[1].strip()
    elif line.startswith('core id'): c=line.split(':')[1].strip()
    elif line.strip()=='' :
        if p is not None and c is not None: pairs.add((p,c))
        p=c=None
if p is not None and c is not None: pairs.add((p,c))
print('unique pairs:', len(pairs))
"
